PRAGMA user_version = 2;
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
    id BLOB PRIMARY KEY,
    account_key BLOB NOT NULL UNIQUE,
    created_at INTEGER NOT NULL
) WITHOUT ROWID;
INSERT INTO users VALUES(x'5707d1a20ddbb0ab66a7ad8e8a20175d',x'a23ae1bcda4e507f6ea71b516fcb88c166f63d707be67edbdc7c4daef89b8956',1794761206761);
INSERT INTO users VALUES(x'81ca01e25b95ba8d60f812b91f9c1a2e',x'096f0e8fa4f50e6e0f5ca952e20fbf7498b0d34feea5a74b0291623971bebe94',1794761206765);
CREATE TABLE account_keys (
    key BLOB PRIMARY KEY,
    user_id BLOB NOT NULL REFERENCES users(id)
) WITHOUT ROWID;
INSERT INTO account_keys VALUES(x'a23ae1bcda4e507f6ea71b516fcb88c166f63d707be67edbdc7c4daef89b8956',x'5707d1a20ddbb0ab66a7ad8e8a20175d');
INSERT INTO account_keys VALUES(x'096f0e8fa4f50e6e0f5ca952e20fbf7498b0d34feea5a74b0291623971bebe94',x'81ca01e25b95ba8d60f812b91f9c1a2e');
CREATE TABLE handles (
    kind INTEGER NOT NULL,
    value BLOB NOT NULL,
    user_id BLOB NOT NULL REFERENCES users(id),
    spelling TEXT,
    PRIMARY KEY (kind, value)
) WITHOUT ROWID;
INSERT INTO handles VALUES(2,x'4a4f',x'5707d1a20ddbb0ab66a7ad8e8a20175d','Jo');
INSERT INTO handles VALUES(2,x'50414c',x'81ca01e25b95ba8d60f812b91f9c1a2e','Pal');
CREATE TABLE reserved (
    skeleton TEXT PRIMARY KEY,
    spelling TEXT NOT NULL,
    note TEXT,
    created_at INTEGER NOT NULL
) WITHOUT ROWID;
CREATE TABLE devices (
    id BLOB PRIMARY KEY,
    user_id BLOB NOT NULL REFERENCES users(id),
    device_key BLOB NOT NULL UNIQUE,
    auth_key BLOB NOT NULL,
    push_platform INTEGER NOT NULL,
    push_token BLOB NOT NULL,
    created_at INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    app TEXT,
    registration_id INTEGER NOT NULL DEFAULT 0,
    number INTEGER NOT NULL DEFAULT 1,
    -- The highest one-time prekey id it uploaded: one not above it is one it uploaded before (a repeat), never taken
    -- again, so a key handed out once is not handed out again.
    prekey_max INTEGER NOT NULL DEFAULT 0
) WITHOUT ROWID;
