CREATE TABLE messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    device_id BLOB NOT NULL,
    envelope BLOB NOT NULL,
    received_at INTEGER NOT NULL
);
INSERT INTO messages VALUES(3,x'733dc1083cb7352eea6b039a69df42ec',x'',1794761206777);
INSERT INTO messages VALUES(4,x'fa1fb418c9b9ac49cd7ae9683042bde6',x'',1794761206782);
