CREATE TABLE backups (
    user_id BLOB PRIMARY KEY REFERENCES users(id),
    locator BLOB UNIQUE,
    record BLOB NOT NULL,
    updated_at INTEGER NOT NULL,
    auth_passkey BLOB,
    auth_code BLOB
) WITHOUT ROWID;
CREATE TABLE reports (
    reporter_id BLOB NOT NULL,
    reported_id BLOB NOT NULL,
    reason INTEGER NOT NULL,
    created_at INTEGER NOT NULL,
    PRIMARY KEY (reporter_id, reported_id)
) WITHOUT ROWID;
CREATE TABLE feedback (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id BLOB NOT NULL,
    text TEXT NOT NULL,
    app_version TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    -- 1: a crash report the app sent on its own, without an account (user_id empty)
    auto INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE contact_keys (
    user_id BLOB PRIMARY KEY REFERENCES users(id),
    current BLOB NOT NULL,
    requests_open INTEGER NOT NULL DEFAULT 1
) WITHOUT ROWID;
INSERT INTO contact_keys VALUES(x'5707d1a20ddbb0ab66a7ad8e8a20175d',x'92beb05414f061f51a2e3d891c95d6c5a79d490d6a57a76b5ec195d069372a7f',1);
INSERT INTO contact_keys VALUES(x'81ca01e25b95ba8d60f812b91f9c1a2e',x'423e57a21f2cf7a1d61e32ef3bc8a742bde3f3103c78fcd825e22c72de1f0a3e',1);
CREATE TABLE requests (
    sender BLOB NOT NULL,
    recipient BLOB NOT NULL,
    day INTEGER NOT NULL,
    n INTEGER NOT NULL,
    PRIMARY KEY (sender, day, recipient)
) WITHOUT ROWID;
CREATE TABLE storage (
    user_id BLOB PRIMARY KEY,
    version INTEGER NOT NULL,
    data BLOB NOT NULL,
    updated_at INTEGER NOT NULL
) WITHOUT ROWID;
INSERT INTO storage VALUES(x'5707d1a20ddbb0ab66a7ad8e8a20175d',1,x'',1794761206778);
CREATE TABLE blobs (
    id BLOB PRIMARY KEY,
    user_id BLOB NOT NULL,
    size INTEGER NOT NULL,
    fetches_left INTEGER NOT NULL,
    created_at INTEGER NOT NULL,
    fetching INTEGER NOT NULL DEFAULT 0,
    ready INTEGER NOT NULL DEFAULT 1
) WITHOUT ROWID;
CREATE TABLE token_keys (
    id INTEGER PRIMARY KEY,
    seed BLOB NOT NULL,
    created_at INTEGER NOT NULL
);
INSERT INTO token_keys VALUES(1,x'40228cd6be70faf21f4d3b89dbac39b14e575cef7f903c231a186f31623153d108b85b923c32a6ada455c8fc393a04dd',1794761206753);
CREATE TABLE spent_tokens (
    nonce BLOB PRIMARY KEY,
    key_id INTEGER NOT NULL
) WITHOUT ROWID;
CREATE TABLE blob_quota (
    user_id BLOB NOT NULL,
    day INTEGER NOT NULL,
    count INTEGER NOT NULL,
    bytes INTEGER NOT NULL,
    PRIMARY KEY (user_id, day)
) WITHOUT ROWID;
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
INSERT INTO sqlite_sequence VALUES('messages',5);
CREATE INDEX account_keys_by_user ON account_keys(user_id);
CREATE INDEX handles_by_user ON handles(user_id, kind);
CREATE INDEX devices_by_user ON devices(user_id);
CREATE INDEX messages_by_device ON messages(device_id, id);
CREATE INDEX messages_by_age ON messages(received_at);
CREATE INDEX reports_by_reported ON reports(reported_id);
CREATE INDEX feedback_by_user ON feedback(user_id);
CREATE INDEX requests_by_recipient ON requests(recipient, day);
CREATE INDEX blobs_by_user ON blobs(user_id);
CREATE INDEX blobs_by_age ON blobs(created_at);
CREATE INDEX spent_tokens_by_key ON spent_tokens(key_id);
PRAGMA writable_schema=OFF;
COMMIT;
